window.addEventListener('DOMContentLoaded',()=>{const preset=document.querySelector('#openEffects');const stack=document.createElement('span');stack.className='preset-stack';stack.setAttribute('aria-hidden','true');stack.innerHTML='<i></i><i></i><i></i>';preset.prepend(stack);document.querySelectorAll('.range input').forEach(input=>{const range=input.closest('.range');const end=()=>range.classList.remove('is-adjusting');input.addEventListener('pointerdown',()=>{if(!input.disabled)range.classList.add('is-adjusting')});input.addEventListener('pointerup',end);input.addEventListener('pointercancel',end);input.addEventListener('blur',end);window.addEventListener('pointerup',end)});document.querySelectorAll('.toolbuttons button').forEach(button=>button.addEventListener('pointermove',e=>{if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;const r=button.getBoundingClientRect();button.style.setProperty('--shine-x',(e.clientX-r.x)/r.width*100+'%')}));});
